// .newera/vm/browser-daemon.mjs — NewEra browser daemon (v16).
// Line-JSON RPC over stdio. Generated by the VM runner; do not edit.
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as url from 'node:url';
import { createRequire } from 'node:module';

const root = process.argv[2] ? path.resolve(process.argv[2]) : process.cwd();
const runtimeDir = path.join(root, '.newera', 'browser-runtime');
const DEFAULT_OP_TIMEOUT_MS = 30_000;
const MAX_OP_TIMEOUT_MS = 180_000;
const IDLE_EXIT_MS = 15 * 60 * 1000;
const LAUNCH_ARGS = ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'];

const EXECUTABLE_CANDIDATES = [
  '/usr/bin/google-chrome',
  '/usr/bin/google-chrome-stable',
  '/usr/bin/chromium',
  '/usr/bin/chromium-browser',
  '/usr/bin/microsoft-edge',
  '/opt/google/chrome/chrome',
  '/snap/bin/chromium',
];

let pw = null;
let browser = null;
let context = null;
let pages = [];
let activePage = 0;
let refSelectors = new Map();
let lastNavigationAt = 0;
const consoleLog = [];
const requestLog = [];
let routeRules = [];

function err(msg) { process.stderr.write('[browser-daemon] ' + msg + '\n'); }

function writeReply(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

async function loadPlaywright() {
  if (pw) return pw;
  const candidates = [
    path.join(runtimeDir, 'node_modules', 'playwright-core'),
    path.join(runtimeDir, 'node_modules', 'playwright'),
  ];
  for (const dir of candidates) {
    try {
      if (fs.existsSync(path.join(dir, 'index.mjs'))) {
        pw = await import(url.pathToFileURL(path.join(dir, 'index.mjs')).href);
        return pw;
      }
      if (fs.existsSync(path.join(dir, 'index.js'))) {
        const req = createRequire(import.meta.url);
        pw = req(dir);
        return pw;
      }
    } catch (e) {
      err('playwright load failed from ' + dir + ': ' + e.message);
    }
  }
  throw new Error(
    'playwright is not installed under ' + runtimeDir +
    ' — the runner installs playwright-core on first browser call; run "npm install --prefix .newera/browser-runtime playwright-core" to fix manually'
  );
}

async function launchBrowser() {
  if (browser && browser.isConnected()) return browser;
  const mod = await loadPlaywright();
  const attempts = [
    function () { return mod.chromium.launch({ channel: 'chrome', headless: true, args: LAUNCH_ARGS }); },
    function () { return mod.chromium.launch({ channel: 'chromium', headless: true, args: LAUNCH_ARGS }); },
    function () { return mod.chromium.launch({ channel: 'msedge', headless: true, args: LAUNCH_ARGS }); },
  ];
  for (const exe of EXECUTABLE_CANDIDATES) {
    if (fs.existsSync(exe)) {
      attempts.push(function () { return mod.chromium.launch({ executablePath: exe, headless: true, args: LAUNCH_ARGS }); });
    }
  }
  attempts.push(function () { return mod.chromium.launch({ headless: true, args: LAUNCH_ARGS }); });
  let lastErr = null;
  for (const attempt of attempts) {
    try {
      browser = await attempt();
      await wireContext();
      return browser;
    } catch (e) {
      lastErr = e;
    }
  }
  throw new Error('no usable chromium/chrome/edge browser found: ' + (lastErr ? lastErr.message : 'unknown'));
}

async function wireContext() {
  const oldContext = context;
  context = await (browser.newContext({ viewport: { width: 1280, height: 800 } }));
  pages = [await context.newPage()];
  activePage = 0;
  attachPage(pages[0]);
  if (oldContext) { try { await oldContext.close(); } catch (e) { /* replaced */ } }
  await applyRouteRules();
}

function page() {
  if (!pages.length) throw new Error('no open page — call browser_navigate first');
  return pages[Math.min(activePage, pages.length - 1)];
}

function attachPage(p) {
  p.on('console', function (msg) {
    consoleLog.push({ at: Date.now(), type: msg.type(), text: String(msg.text()).slice(0, 500) });
    if (consoleLog.length > 100) consoleLog.shift();
  });
  p.on('request', function (req) {
    requestLog.push({ at: Date.now(), method: req.method(), url: req.url(), resourceType: req.resourceType() });
    if (requestLog.length > 200) requestLog.shift();
  });
  p.on('pageerror', function (e) {
    consoleLog.push({ at: Date.now(), type: 'pageerror', text: String(e && e.message ? e.message : e).slice(0, 500) });
    if (consoleLog.length > 100) consoleLog.shift();
  });
  p.on('framenavigated', function (frame) {
    if (frame === p.mainFrame()) { refSelectors.clear(); lastNavigationAt = Date.now(); }
  });
}

async function applyRouteRules() {
  if (!context) return;
  await context.unroute('**/*').catch(function () {});
  routeRules = routeRules.filter(function (r) { return r && r.pattern; });
  if (!routeRules.length) return;
  await context.route('**/*', async function (route) {
    const reqUrl = route.request().url();
    for (const rule of routeRules) {
      try {
        const re = new RegExp(rule.pattern);
        if (!re.test(reqUrl)) continue;
        if (rule.action === 'abort') return await route.abort();
        if (rule.action === 'fulfill') {
          return await route.fulfill({
            status: rule.status || 200,
            contentType: rule.contentType || 'text/plain',
            body: rule.body == null ? '' : String(rule.body),
          });
        }
        break;
      } catch (e) { /* bad pattern — skip */ }
    }
    return await route.continue();
  });
}

function clampTimeout(v) {
  const n = Math.floor(Number(v));
  if (!Number.isFinite(n) || n <= 0) return DEFAULT_OP_TIMEOUT_MS;
  return Math.min(MAX_OP_TIMEOUT_MS, n * 1); // caller sends ms
}

async function withTimeout(promise, ms, label) {
  let timer = null;
  try {
    return await Promise.race([
      promise,
      new Promise(function (_resolve, reject) {
        timer = setTimeout(function () {
          reject(new Error(label + ' timed out after ' + ms + 'ms'));
        }, ms);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/* ── the ops ─────────────────────────────────────────────────────────────── */

const OPS = {
  async status() {
    let version = null;
    try {
      const pkg = path.join(runtimeDir, 'node_modules', 'playwright-core', 'package.json');
      version = JSON.parse(fs.readFileSync(pkg, 'utf8')).version || null;
    } catch (e) { version = null; }
    return {
      playwright: version,
      browser: Boolean(browser && browser.isConnected()),
      pages: pages.length,
      activePage: activePage,
      url: pages.length ? page().url() : null,
    };
  },

  async navigate(args) {
    await launchBrowser();
    const target = String(args.url || '');
    // http(s) for the web + file:// for LOCAL static output (previewing the
    // job's own built site without a server) — the daemon runs inside the job
    // VM, so a local file URL crosses no security boundary.
    if (!/^(https?|file):\/\//i.test(target)) throw new Error('url must be http(s):// or file://');
    const waitUntil = ['load', 'domcontentloaded', 'networkidle'].includes(args.wait_until) ? args.wait_until : 'load';
    const p = page();
    const resp = await p.goto(target, { waitUntil: waitUntil, timeout: clampTimeout(args.timeout_ms) });
    return { url: p.url(), title: await p.title(), status: resp ? resp.status() : null };
  },

  async back() { await page().goBack({ waitUntil: 'domcontentloaded' }); return { url: page().url() }; },
  async forward() { await page().goForward({ waitUntil: 'domcontentloaded' }); return { url: page().url() }; },
  async reload() { await page().reload({ waitUntil: 'domcontentloaded' }); return { url: page().url() }; },

  async snapshot() {
    const p = page();
    const shot = await p.evaluate(function () {
      const out = [];
      const refs = {};
      let refCounter = 0;
      const INTERACTIVE = ['a', 'button', 'input', 'select', 'textarea', 'label', 'summary', 'option'];
      const interesting = function (el) {
        const tag = el.tagName.toLowerCase();
        if (INTERACTIVE.indexOf(tag) >= 0) return true;
        if (el.getAttribute('role')) return true;
        if (el.hasAttribute('onclick')) return true;
        if (el.getAttribute('contenteditable')) return true;
        return false;
      };
      const selectorFor = function (el) {
        if (el.id) return '#' + (window.CSS && CSS.escape ? CSS.escape(el.id) : el.id);
        const parts = [];
        let cur = el;
        let guard = 0;
        while (cur && cur.nodeType === 1 && guard < 14) {
          guard += 1;
          let sel = cur.tagName.toLowerCase();
          if (sel === 'html' || sel === 'body') { parts.unshift(sel); break; }
          const parent = cur.parentElement;
          if (parent) {
            const sameTag = Array.from(parent.children).filter(function (c) { return c.tagName === cur.tagName; });
            if (sameTag.length > 1) sel += ':nth-of-type(' + (sameTag.indexOf(cur) + 1) + ')';
          }
          parts.unshift(sel);
          cur = parent;
        }
        return parts.join(' > ');
      };
      const walk = function (node, depth) {
        if (out.length > 500 || depth > 30) return;
        if (node.nodeType !== 1) return;
        const el = node;
        const style = window.getComputedStyle(el);
        if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return;
        const tag = el.tagName.toLowerCase();
        if (interesting(el)) {
          refCounter += 1;
          const ref = 'e' + refCounter;
          const rawLabel =
            el.getAttribute('aria-label') ||
            el.innerText ||
            el.value ||
            el.getAttribute('placeholder') ||
            el.getAttribute('title') ||
            el.getAttribute('name') ||
            '';
          const label = String(rawLabel).replace(/\s+/g, ' ').trim().slice(0, 140);
          const roleMap = { a: 'link', button: 'button', select: 'combobox', textarea: 'textbox', summary: 'button', option: 'option', label: 'label' };
          let role = el.getAttribute('role') || roleMap[tag] || tag;
          if (tag === 'input') role = el.type === 'checkbox' || el.type === 'radio' ? (el.type + (el.checked ? ' [checked]' : '')) : 'textbox:' + (el.type || 'text');
          refs[ref] = selectorFor(el);
          out.push(new Array(depth + 1).join('  ') + '[' + ref + '] ' + role + (label ? ' "' + label + '"' : '') + (el.disabled ? ' (disabled)' : ''));
        }
        for (let i = 0; i < el.children.length; i++) walk(el.children[i], depth + 1);
      };
      if (document.body) walk(document.body, 0);
      return {
        title: document.title || '',
        url: location.href,
        tree: out.join('\n') || '(no interactive elements)',
        refs: refs,
        textSample: (document.body ? document.body.innerText : '').replace(/\s+\n/g, '\n').slice(0, 1200),
      };
    });
    refSelectors.clear();
    for (const ref of Object.keys(shot.refs)) refSelectors.set(ref, shot.refs[ref]);
    return shot;
  },

  async click(args) {
    const p = page();
    const timeout = clampTimeout(args.timeout_ms);
    if (args.ref) {
      const sel = refSelectors.get(String(args.ref));
      if (!sel) throw new Error('unknown ref ' + args.ref + ' — take a fresh browser_snapshot first (refs reset on navigation)');
      await p.locator(sel).first().click({ timeout: timeout });
      return { clicked: String(args.ref), selector: sel };
    }
    const selector = String(args.selector || '');
    if (!selector) throw new Error('ref (from snapshot) or selector is required');
    await p.locator(selector).first().click({ timeout: timeout });
    return { clicked: selector };
  },

  async type(args) {
    const p = page();
    const timeout = clampTimeout(args.timeout_ms);
    const text = String(args.text == null ? '' : args.text);
    let loc = null;
    if (args.ref) {
      const sel = refSelectors.get(String(args.ref));
      if (!sel) throw new Error('unknown ref ' + args.ref + ' — take a fresh browser_snapshot first');
      loc = p.locator(sel).first();
    } else if (args.selector) {
      loc = p.locator(String(args.selector)).first();
    } else {
      await p.keyboard.insertText(text);
      return { typed: 'keyboard', chars: text.length };
    }
    await loc.fill(text, { timeout: timeout });
    if (args.press_enter) await loc.press('Enter');
    return { typed: args.ref || args.selector, chars: text.length, submitted: Boolean(args.press_enter) };
  },

  async press(args) {
    const key = String(args.key || '');
    if (!key) throw new Error('key is required (e.g. Enter, Tab, ArrowDown, Control+a)');
    await page().keyboard.press(key);
    return { pressed: key };
  },

  async screenshot(args) {
    const p = page();
    const target = args.path ? path.resolve(root, String(args.path)) : null;
    const buf = await p.screenshot({
      fullPage: args.full_page === true,
      ...(target ? { path: target } : {}),
    });
    return {
      bytes: buf ? buf.length : 0,
      ...(target ? { path: path.relative(root, target) } : {}),
      dataUri: 'data:image/png;base64,' + Buffer.from(buf).toString('base64'),
    };
  },

  async extract(args) {
    const p = page();
    if (args.selector) {
      const data = await p.locator(String(args.selector)).first().innerText({ timeout: clampTimeout(args.timeout_ms) });
      return { url: p.url(), title: await p.title(), selected: data.slice(0, 20000) };
    }
    const data = await p.evaluate(function () {
      const links = Array.from(document.querySelectorAll('a[href]')).slice(0, 150).map(function (a) {
        return { text: String(a.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 100), href: a.href };
      });
      const inputs = Array.from(document.querySelectorAll('input, select, textarea')).slice(0, 80).map(function (el) {
        return { tag: el.tagName.toLowerCase(), type: el.type || null, name: el.name || null, id: el.id || null, value: el.type === 'password' ? '***' : String(el.value || '').slice(0, 120) };
      });
      return {
        title: document.title || '',
        url: location.href,
        text: (document.body ? document.body.innerText : '').slice(0, 20000),
        links: links,
        inputs: inputs,
      };
    });
    return data;
  },

  async evaluate(args) {
    const code = String(args.js || args.code || '');
    if (!code.trim()) throw new Error('js is required');
    const result = await page().evaluate(new Function('return (async () => {' + code + '})()'));
    return { result: result === undefined ? null : JSON.parse(JSON.stringify(result)) };
  },

  async wait(args) {
    const p = page();
    const timeout = clampTimeout(args.timeout_ms);
    if (args.selector) { await p.waitForSelector(String(args.selector), { timeout: timeout }); return { waited: 'selector', selector: String(args.selector) }; }
    if (args.text) { await p.waitForSelector('text=' + String(args.text), { timeout: timeout }).catch(function () { return p.waitForFunction(function (t) { return document.body && document.body.innerText.indexOf(t) >= 0; }, String(args.text), { timeout: timeout }); }); return { waited: 'text', text: String(args.text) }; }
    if (args.url_pattern) { await p.waitForURL(new RegExp(String(args.url_pattern)), { timeout: timeout }); return { waited: 'url', pattern: String(args.url_pattern) }; }
    const ms = Math.min(30000, Math.max(100, Math.floor(Number(args.ms) || 1000)));
    await p.waitForTimeout(ms);
    return { waited: ms + 'ms' };
  },

  async hover(args) {
    const p = page();
    if (args.ref) {
      const sel = refSelectors.get(String(args.ref));
      if (!sel) throw new Error('unknown ref ' + args.ref);
      await p.locator(sel).first().hover({ timeout: clampTimeout(args.timeout_ms) });
      return { hovered: String(args.ref) };
    }
    await p.locator(String(args.selector || '')).first().hover({ timeout: clampTimeout(args.timeout_ms) });
    return { hovered: String(args.selector) };
  },

  async select_option(args) {
    const p = page();
    const loc = args.ref
      ? p.locator(refSelectors.get(String(args.ref)) || String(args.ref || '')).first()
      : p.locator(String(args.selector || '')).first();
    const value = args.value == null ? [] : Array.isArray(args.value) ? args.value.map(String) : [String(args.value)];
    const selected = await loc.selectOption(value.length === 1 ? value[0] : value, { timeout: clampTimeout(args.timeout_ms) });
    return { selected: selected };
  },

  async check(args) {
    const loc = args.ref
      ? page().locator(refSelectors.get(String(args.ref)) || '').first()
      : page().locator(String(args.selector || '')).first();
    if (args.uncheck === true) { await loc.uncheck({ timeout: clampTimeout(args.timeout_ms) }); return { unchecked: true }; }
    await loc.check({ timeout: clampTimeout(args.timeout_ms) });
    return { checked: true };
  },

  async scroll(args) {
    const p = page();
    if (args.to_end === true || args.direction) {
      const dir = args.direction === 'up' ? -1 : 1;
      await p.evaluate(function (d) { window.scrollBy(0, d * (document.body ? document.body.scrollHeight : 10000)); }, dir);
      return { scrolled: args.direction || 'down' };
    }
    const amount = Math.max(1, Math.min(50000, Math.floor(Number(args.amount) || 600)));
    await p.evaluate(function (a) { window.scrollBy(0, a); }, amount);
    return { scrolled: amount + 'px' };
  },

  async set_viewport(args) {
    const w = Math.max(200, Math.min(4000, Math.floor(Number(args.width) || 1280)));
    const h = Math.max(200, Math.min(8000, Math.floor(Number(args.height) || 800)));
    await page().setViewportSize({ width: w, height: h });
    return { viewport: { width: w, height: h } };
  },

  async pdf(args) {
    const p = page();
    const target = path.resolve(root, String(args.path || 'page.pdf'));
    await p.pdf({ path: target, format: args.format || 'A4', printBackground: args.print_background !== false });
    return { path: path.relative(root, target) };
  },

  async cookies_get() {
    if (!context) throw new Error('no browser open — call browser_navigate first');
    return { cookies: await context.cookies() };
  },

  async cookies_set(args) {
    if (!context) throw new Error('no browser open — call browser_navigate first');
    const cookies = Array.isArray(args.cookies) ? args.cookies : [];
    await context.addCookies(cookies);
    return { set: cookies.length };
  },

  async set_route(args) {
    routeRules = Array.isArray(args.rules) ? args.rules.slice(0, 50) : [];
    if (context) await applyRouteRules();
    return { rules: routeRules.length };
  },

  async requests(args) {
    const n = Math.max(1, Math.min(200, Math.floor(Number(args && args.last) || 40)));
    return { requests: requestLog.slice(-n) };
  },

  async console() {
    return { console: consoleLog.slice(-40) };
  },

  async tabs_list() {
    const list = [];
    for (let i = 0; i < pages.length; i++) {
      list.push({ index: i, active: i === activePage, url: pages[i].url() });
    }
    return { tabs: list };
  },

  async tabs_new(args) {
    await launchBrowser();
    const p = await context.newPage();
    attachPage(p);
    pages.push(p);
    activePage = pages.length - 1;
    if (args.url && /^https?:\/\//i.test(String(args.url))) {
      await p.goto(String(args.url), { waitUntil: 'domcontentloaded' }).catch(function (e) { err('tab goto failed: ' + e.message); });
    }
    return { tab: activePage, url: p.url() };
  },

  async tabs_switch(args) {
    const idx = Math.floor(Number(args.index));
    if (!(idx >= 0 && idx < pages.length)) throw new Error('tab index out of range (0..' + (pages.length - 1) + ')');
    activePage = idx;
    return { tab: idx, url: pages[idx].url() };
  },

  async tabs_close(args) {
    const idx = args.index == null ? activePage : Math.floor(Number(args.index));
    if (pages.length <= 1) throw new Error('cannot close the last tab');
    if (!(idx >= 0 && idx < pages.length)) throw new Error('tab index out of range');
    const closing = pages[idx];
    pages.splice(idx, 1);
    await closing.close().catch(function () {});
    if (activePage >= pages.length) activePage = pages.length - 1;
    return { closed: idx, activePage: activePage };
  },

  async close() {
    if (browser) { try { await browser.close(); } catch (e) { /* already dead */ } }
    browser = null; context = null; pages = []; refSelectors.clear();
    return { closed: true };
  },
};

/* ── the RPC loop ────────────────────────────────────────────────────────── */

let idleTimer = null;
function resetIdle() {
  if (idleTimer) clearTimeout(idleTimer);
  idleTimer = setTimeout(function () {
    err('idle for ' + (IDLE_EXIT_MS / 60000) + ' min — closing browser and exiting');
    const t = setTimeout(function () { process.exit(0); }, 3000);
    t.unref();
    if (browser) browser.close().catch(function () { process.exit(0); });
    else process.exit(0);
  }, IDLE_EXIT_MS);
  idleTimer.unref();
}
resetIdle();

async function handleCommand(cmd) {
  const id = cmd.id;
  const op = String(cmd.op || '');
  const fn = OPS[op];
  if (!fn) {
    writeReply({ id: id, ok: false, error: 'unknown op "' + op + '" — ops: ' + Object.keys(OPS).sort().join(', ') });
    return;
  }
  try {
    const result = await withTimeout(Promise.resolve().then(function () { return fn(cmd.args || {}); }), clampTimeout(cmd.args && cmd.args.timeout_ms), op);
    writeReply({ id: id, ok: true, result: result });
  } catch (e) {
    writeReply({ id: id, ok: false, error: String((e && e.message) || e).slice(0, 600) });
  }
}

let buffer = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', function (chunk) {
  buffer += chunk;
  let idx;
  while ((idx = buffer.indexOf('\n')) >= 0) {
    const line = buffer.slice(0, idx).trim();
    buffer = buffer.slice(idx + 1);
    if (!line) continue;
    resetIdle();
    let cmd = null;
    try { cmd = JSON.parse(line); } catch (e) {
      writeReply({ id: null, ok: false, error: 'unparseable command line: ' + String(e && e.message).slice(0, 200) });
      continue;
    }
    if (cmd && typeof cmd.id !== 'undefined' && typeof cmd.op === 'string') {
      handleCommand(cmd);
    }
  }
});
process.stdin.on('end', function () {
  err('stdin closed — exiting');
  process.exit(0);
});
process.on('uncaughtException', function (e) {
  err('uncaught: ' + (e && e.stack ? e.stack : e));
  writeReply({ id: null, ok: false, error: 'daemon uncaught exception: ' + String(e && e.message).slice(0, 300) });
});
writeReply({ id: 'boot', ok: true, result: { daemon: 'ready', node: process.version } });
